output:
    plates.push({
      index: i,
      group: plateGroup,
      photoMesh,
      frameMesh,
      stripMesh,
      stripEmissiveUniform,
      captionMesh,
      baseY,
    });
  }

  // --- entrance animation (rise-in, staggered) ---
  const entranceTweens = [];
  plates.forEach((plate, idx) => {
    plate.group.position.y = plate.baseY + 0.4;
    const t = gsap.to(plate.group.position, {
      y: plate.baseY,
      duration: 0.7,
      ease: 'power3.out',
      delay: idx * 0.08,
    });
    entranceTweens.push(t);
  });
  if (headlineMesh) {
    headlineMesh.position.y = 1.9 + 0.4;
    const ht = gsap.to(headlineMesh.position, {
      y: 1.9,
      duration: 0.7,
      ease: 'power3.out',
    });
    entranceTweens.push(ht);
    const hs = gsap.to(headlineMesh.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.7,
      ease: 'power3.out',
    });
    entranceTweens.push(hs);
  }

  // --- focus reveal helpers (scale/position based, avoids touching MSDF material internals) ---
  function showCaption(plate) {
    const mesh = plate.captionMesh;
    if (!mesh) return;
    gsap.killTweensOf(mesh.scale);
    gsap.killTweensOf(mesh.position);
    mesh.visible = true;
    mesh.position.y = -0.05;
    gsap.to(mesh.scale, { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power2.out' });
    gsap.to(mesh.position, { y: 0, duration: 0.5, ease: 'power2.out' });
  }

  function hideCaption(plate) {
    const mesh = plate.captionMesh;
    if (!mesh) return;
    gsap.killTweensOf(mesh.scale);
    gsap.killTweensOf(mesh.position);
    gsap.to(mesh.scale, {
      x: 0.001,
      y: 0.001,
      z: 0.001,
      duration: 0.3,
      ease: 'power2.out',
      onComplete: () => {
        mesh.visible = false;
      },
    });
  }

  let focusedIndex = -1;

  function setFocus(newIndex) {
    const prev = focusedIndex >= 0 ? plates[focusedIndex] : null;
    const next = plates[newIndex];
    if (prev) {
      gsap.killTweensOf(prev.photoMesh.scale);
      gsap.to(prev.photoMesh.scale, { x: 1, y: 1, z: 1, duration: 0.35, ease: 'power3.out' });
      gsap.killTweensOf(prev.stripEmissiveUniform);
      gsap.to(prev.stripEmissiveUniform, { value: 0, duration: 0.3, ease: 'power2.out' });
      hideCaption(prev);
    }
    if (next) {
      gsap.killTweensOf(next.photoMesh.scale);
      gsap.to(next.photoMesh.scale, {
        x: 1.06,
        y: 1.06,
        z: 1.06,
        duration: 0.35,
        ease: 'power3.out',
      });
      gsap.killTweensOf(next.stripEmissiveUniform);
      gsap.to(next.stripEmissiveUniform, { value: 1.4, duration: 0.3, ease: 'power2.out' });
      showCaption(next);
    }
    focusedIndex = newIndex;
  }

  // --- weighted-settle bounce on scroll stop ---
  let settleTimer = null;
  function scheduleSettle() {
    if (settleTimer) settleTimer.kill();
    settleTimer = gsap.delayedCall(0.18, () => {
      gsap.killTweensOf(plateColumn.scale);
      gsap.fromTo(
        plateColumn.scale,
        { x: 1, y: 1.04, z: 1 },
        { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
      );
    });
  }

  // --- scroll-driven, damped, looping column motion ---
  let currentY = 0;
  let scrollTarget = 0;
  let lastScrollTarget = 0;

  function tick() {
    const dt = gsap.ticker.deltaRatio(60) / 60;
    // gentle autonomous drift keeps the loop cycling even absent explicit scroll input
    scrollTarget += dt * 0.1;
    if (scrollTarget !== lastScrollTarget) {
      lastScrollTarget = scrollTarget;
      scheduleSettle();
    }
    const diff = scrollTarget - currentY;
    currentY += diff * DAMPING;
    plateColumn.position.y = wrapMod(currentY, LOOP_MOD);

    let nearestIndex = 0;
    let nearestDist = Infinity;
    for (const plate of plates) {
      const rawY = plateColumn.position.y + plate.baseY;
      const centered = wrapMod(rawY + LOOP_MOD / 2, LOOP_MOD) - LOOP_MOD / 2;
      const d = Math.abs(centered);
      if (d < nearestDist) {
        nearestDist = d;
        nearestIndex = plate.index;
      }
    }
    if (nearestIndex !== focusedIndex) {
      setFocus(nearestIndex);
    }
  }

  gsap.ticker.add(tick);

  // --- cinematic primitives ---
  const primitiveCleanups = [];
  const primitiveRefs = Array.isArray(config.cinematicPrimitives) ? config.cinematicPrimitives : [];
  primitiveRefs.forEach((prim) => {
    const fn = ctx.primitives && ctx.primitives[prim.name];
    if (typeof fn !== 'function') return;
    const result = fn(group, prim.params || {});
    if (typeof result === 'function') {
      primitiveCleanups.push(result);
    } else if (result && typeof result.cleanup === 'function') {
      primitiveCleanups.push(() => result.cleanup());
    }
  });

  // --- interaction handlers ---
  function handleWheel(delta) {
    const d = typeof delta === 'number' ? delta : 0;
    scrollTarget += d * WHEEL_SCALE;
  }

  group.userData.handlers = {
    onWheel: handleWheel,
    onScroll: handleWheel,
  };

  // --- cleanup ---
  group.userData.cleanup = () => {
    gsap.ticker.remove(tick);
    if (settleTimer) settleTimer.kill();
    entranceTweens.forEach((t) => t.kill());
    gsap.killTweensOf(plateColumn.position);
    gsap.killTweensOf(plateColumn.scale);
    if (headlineMesh) {
      gsap.killTweensOf(headlineMesh.position);
      gsap.killTweensOf(headlineMesh.scale);
    }

    plates.forEach((plate) => {
      gsap.killTweensOf(plate.photoMesh.scale);
      gsap.killTweensOf(plate.stripEmissiveUniform);
      if (plate.captionMesh) {
        gsap.killTweensOf(plate.captionMesh.scale);
        gsap.killTweensOf(plate.captionMesh.position);
      }
    });

    disposableGeometries.forEach((g) => g.dispose());
    disposableMaterials.forEach((m) => m.dispose());
    disposableTexts.forEach((t) => disposeText(t));

    primitiveCleanups.forEach((fn) => {
      try {
        fn();
      } catch (e) {
        /* noop */
      }
    });

    plates.length = 0;
    disposableGeometries.length = 0;
    disposableMaterials.length = 0;
    disposableTexts.length = 0;
    primitiveCleanups.length = 0;
  };

  return group;
}
